<template>
  <div>
    <div class="app-content content">
      <div class="content-wrapper">
        <div class="content-header row">
          <div class="content-header-left col-12 mb-1 mt-0">
            <div class="row breadcrumbs-top">
              <div class="col-sm-9">
                <div class="breadcrumb-wrapper col-9">
                  <ol class="breadcrumb p-0 mb-0">
                    <li class="breadcrumb-item">
                      <router-link :to="{ path: '/' }"
                        ><i class="bx bx-home-alt"></i
                      ></router-link>
                    </li>
                    <li class="breadcrumb-item active">
                      Monthly Date range 
                    </li>
                  </ol>
                </div>
              </div>
              <!--                        <div class=" col-sm-3">
                            <a class="btn btn-primary add-btn" @click="update()" > <i class="bx bx-add-alt"></i> Update</a>       
                        </div> -->
            </div>
          </div>
        </div>
        <div class="content-body">
          <!-- Zero configuration table -->
          <section id="basic-datatable">
            <div class="row">
              <div class="col-12">
                <div class="card">
                  <!--  -->
                  <div class="card-content">
                    <div class="d-inline-flex col-lg-12">
                      <!--                         <div class="col-sm-3 col-lg-3" >
                                            <label for="users-list-verified">Report Name</label>
                                            <fieldset class="form-group">
                                                <select class="form-control"  v-model="updateForm.permission_for" @change="getItems(updateForm.permission_for)" id="users-list-verified" >
                                                    <option value=0>Monthly Summery Report Permission</option>
                                                    <option value=1>KRA KPI Report Settings(ADD ,EDIT & DELETE)</option>
                                                </select>
                                            </fieldset>
                                        </div> -->
                      <div class="col-sm-2 col-lg-2">
                        <label for="users-list-verified"> </label>
                        <fieldset class="form-group">
                          <button
                            type="button"
                            class="
                              btn btn-primary
                              add-btn
                              btn-lg
                              d-flex
                              align-items-center
                            "
                          >
                            <a class="text-white" @click="update()">
                              <i class="bx bx-add-alt"></i> Update</a
                            >
                          </button>
                        </fieldset>
                      </div>
                    </div>
                    <div class="card-body card-dashboard">
                      <div class="table-responsive">
                        <table class="table table-striped">
                          <thead>
                            <tr>
                              <th>SL</th>
                              <th>Dept Name</th>
                              <th>
                                <div v-if="checked_all == true" class="row">
                                  <div class="col-12 col-sm-6">
                                    <label class="control-label">
                                      Start Date
                                    </label>
                                    <fieldset class="form-group">
                                      <datepicker
                                        @closed="startDateClosedFunction"
                                        v-model="start_date"
                                        name="start_date"
                                        class="form-control"
                                      ></datepicker>
                                    </fieldset>
                                  </div>
                                  <div class="col-12 col-sm-6">
                                    <label class="control-label"
                                      >End Date
                                    </label>
                                    <fieldset class="form-group">
                                      <datepicker
                                        @closed="endDateClosedFunction"
                                        v-model="end_date"
                                        name="end_date"
                                        class="form-control"
                                      ></datepicker>
                                    </fieldset>
                                  </div>
                                </div>
                              </th>
                              <th>
                                Status
                                <input
                                  type="checkbox"
                                  value="1"
                                  @change="check()"
                                  id="checked_all"
                                  v-model="checked_all"
                                />
                              </th>
                            </tr>
                          </thead>
                          <tbody>
                            <template  v-for="(row, index) in items" >  
                              <tr :key="row.id" v-if="row.monthly_date_range"> 
                              <td>{{ index + 1 }}</td>
                              <td>{{ row.name }}</td>
                              <td v-if="row.monthly_date_range.status">
                                <div class="row">
                                  <div class="col-12 col-sm-6">
                                    <label class="control-label">
                                      Start Date
                                    </label>
                                    <fieldset class="form-group">
                                      <datepicker
                                        @closed="datepickerClosedFunction"
                                        v-model="
                                          row.monthly_date_range.start_date
                                        "
                                        name="start_date"
                                        class="form-control"
                                      ></datepicker>
                                    </fieldset>
                                  </div>
                                  <div class="col-12 col-sm-6">
                                    <label class="control-label"
                                      >End Date
                                    </label>
                                    <fieldset class="form-group">
                                      <datepicker
                                        @closed="datepickerClosedFunction"
                                        v-model="
                                          row.monthly_date_range.end_date
                                        "
                                        name="end_date"
                                        class="form-control"
                                      ></datepicker>
                                    </fieldset>
                                  </div>
                                </div>
                              </td>
                              <td v-if="!row.monthly_date_range.status"></td>
                              <td>
                                <input
                                  type="checkbox"
                                  value="1"
                                  v-model="row.monthly_date_range.status"
                                />
                              </td>
                            </tr>
                            </template>
                            <tr v-if="items.length < 1">
                              <td colspan="4">Data not found</td>
                            </tr>
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import { Form } from "vform";
import axios from "../../axios_instance";
import Datepicker from "vuejs-datepicker";
export default {
  props: {},
  components: {
    Datepicker,
    // VueRecaptcha, facebookLogin
  },
  data() {
    return {
      start_date: "",
      end_date: "",
      checked_all: false,
      checkbox: false,
      base_url: window.base_url,
      api_url: window.api_url,
      permission_for: 0,
      token: this.$localStorage.get("d_token"),
      items: [],
      status: "",
      updateForm: new Form({
        items: "",
        permission_for: this.$route.params.id,
      }),
      state: {
        disabledDates: {
          to: new Date(2021, 0, 0), // Disable all dates up to specific date
          from: new Date(2022, 0, 0), // Disable all dates after specific date
        },
      },
    };
  },
  created() {
    this.getItems(this.permission_for);
  },
  methods: {
    check() {
      console.log(this.checked_all);
      for (let index = 0; index < this.items.length; index++) {
        this.items[index].monthly_date_range.status = this.checked_all;
      }
    },
    datepickerClosedFunction() {},
    startDateClosedFunction() {
      console.log(this.start_date);
      for (let index = 0; index < this.items.length; index++) {
        this.items[index].monthly_date_range.start_date = this.start_date;
      }
    },
    endDateClosedFunction() {
      console.log(this.start_date);
      for (let index = 0; index < this.items.length; index++) {
        this.items[index].monthly_date_range.end_date = this.end_date;
      }
    },
    update() {
      let loader = this.$loading.show();
      this.updateForm.items = this.items;
      this.updateForm.permission_for = this.permission_for;
      console.log("this.updateForm", this.updateForm);
      this.updateForm
        .post(this.api_url + "department_monthly_report_update", {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then(
          (res) => {
            console.log(res);
            if (res.data.success) {
              this.$toasted.show(res.data.message, {
                theme: "bubble",
                duration: 5000,
                position: "bottom-right",
              });
            }
            loader.hide();
            //this.$router.push('/department');
          },
          (error) => {
            console.log(error);
            loader.hide();
          }
        );
    },

    async getItems(permission_for) {
      let where = "?";
      if (permission_for == 1) {
        where = "?permission_for=1";
      } else {
        where = "?permission_for=0";
      }

      let loader = this.$loading.show();
      await axios
        .get(this.api_url + "monthly_date_range" + where, {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then(({ data }) => {
          this.items = data.data;
          loader.hide();
          console.log(this.WingsItems);
        });
    },
  },
  computed: {},
};
</script>
